    {selected||['text','stamp','comment'].includes(tool)?<><div className="property-tag"><Type size={13}/>{selected?'EXISTING PDF WORD':tool==='comment'?'PDF ANNOTATION':'NEW CONTENT'}</div>{selected&&!selected.editable&&<div className="warning-note">{selected.reason}</div>}<label className="field">{selected?'Selected word':'Your text'}{selected?<textarea aria-label="Replacement word" value={text} rows={4} maxLength={4000} onChange={e=>setText(e.target.value)} disabled={!selected.editable} onKeyDown={e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();applyWordEdit()}else if(e.key==='Escape')setSelected(null)}}/>:<textarea value={text} onChange={e=>setText(e.target.value)} rows={4}/>}</label>{tool!=='comment'&&<><div className="field-row"><label className="field">Font size<input type="number" min="4" max="144" value={size} onChange={e=>{setSize(+e.target.value);setSizeChanged(true)}}/></label><label className="field">Colour<div className="color-input"><input type="color" value={color} onChange={e=>setColor(e.target.value)}/><span>{color.toUpperCase()}</span></div></label></div><label className="field">Font{selected?<input value={selected.font} readOnly/>:<select value={font} onChange={e=>setFont(e.target.value)}><option value="helv">Helvetica</option><option value="tiro">Times Roman</option><option value="cour">Courier</option><option value="hebo">Helvetica Bold</option></select>}</label></>}{selected?<><button className="button primary full" disabled={!selected.editable||!!busy} onClick={()=>applyWordEdit()}><Check size={16}/> Apply word edit</button><p className="help-note">Spaces and paragraphs are supported. Text is never squeezed to fit. Short replacements modify the original text directly. Longer ones remove the original text and become a wrapped, movable text layer in available space. Nearby content is not automatically reflowed.</p></>:<div className="instruction"><MousePointer2 size={19}/><p>Click on the page to place {tool==='comment'?'your comment':'your text'}. Each placement is saved immediately.</p></div>}</>:<><div className="workspace-illustration"><FileText size={45}/><span><PenLine size={20}/></span></div><h3>A small edit.<br/>A fresh perspective.</h3><p className="panel-copy">{textReady?(spans.length?`${spans.filter(s=>s.editable).length} of ${spans.length} words on this page can be edited. Click a word to get started.`:'No selectable text was found on this page. If it is scanned, OCR can make it searchable, but does not reconstruct editable words.'):'Detecting words and checking their PDF fonts…'}</p><div className="context-card"><MousePointer2 size={16}/><div><strong>Word-by-word editing</strong><p>Click an underlined word, type its replacement on the page, and press Enter. Grey words explain why they are read-only.</p></div></div><div className="property-divider"/><span className="mini-label">QUICK ACTIONS</span><button className="quick-action" disabled={!!busy} onClick={()=>{pendingExtra.current='merge';extraInput.current.click()}}><Layers size={17}/>Merge another PDF <Plus size={14}/></button><button className="quick-action" onClick={()=>{setRange('1-'+info.pages.length);setDialog('extract')}}><Scissors size={17}/>Split or extract <ChevronRight size={14}/></button><button className="quick-action" disabled={!!busy} onClick={()=>operation('compress',{},'PDF streams recompressed. Size reduction depends on the source.')}><Download size={17}/>Compress PDF <ChevronRight size={14}/></button><button className="quick-action" onClick={()=>setDialog('tools')}><Settings2 size={17}/>All document tools <ChevronRight size={14}/></button></>}
